create or replace function public.toolbox_issues_list_issues(p_workspace_id uuid,p_where jsonb default null,p_order_by jsonb default null,p_limit integer default 50,p_cursor text default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare off integer:=greatest(coalesce(nullif(p_cursor,'')::integer,0),0); lim integer:=least(greatest(coalesce(p_limit,50),1),500); total integer; items jsonb; col text:=coalesce(p_order_by->>'column',p_order_by->>'by',p_order_by->>'field','updatedAt'); dir text:=lower(coalesce(p_order_by->>'direction',p_order_by->>'order','desc')); begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select count(*) into total from public.toolbox_issues i where i.workspace_id=p_workspace_id and i.archived_at is null and (p_where is null or ((not(p_where?'name') or i.name ilike '%'||(p_where->>'name')||'%') and (not(p_where?'status') or i.status=p_where->>'status') and (not(p_where?'person') or i.person::text ilike '%'||(p_where->>'person')||'%'))); select coalesce(jsonb_agg(private.toolbox_issue_json(x)),'[]'::jsonb) into items from (select i.* from public.toolbox_issues i where i.workspace_id=p_workspace_id and i.archived_at is null and (p_where is null or ((not(p_where?'name') or i.name ilike '%'||(p_where->>'name')||'%') and (not(p_where?'status') or i.status=p_where->>'status') and (not(p_where?'person') or i.person::text ilike '%'||(p_where->>'person')||'%'))) order by case when dir='asc' and col='name' then i.name end asc,case when dir='desc' and col='name' then i.name end desc,case when dir='asc' and col='status' then i.status end asc,case when dir='desc' and col='status' then i.status end desc,case when dir='asc' and col in('date','targetDate') then i.target_date end asc,case when dir='desc' and col in('date','targetDate') then i.target_date end desc,case when dir='asc' and col='createdAt' then i.created_at end asc,case when dir='desc' and col='createdAt' then i.created_at end desc,case when dir='asc' then i.updated_at end asc,case when dir<>'asc' then i.updated_at end desc limit lim offset off)x; return jsonb_build_object('items',items,'cursor',case when off+lim<total then (off+lim)::text else null end,'total',total); end $$; create or replace function public.toolbox_issues_aggregate(p_workspace_id uuid,p_group_by text default 'status',p_alias text default 'count') returns jsonb language plpgsql stable security definer set search_path='' as $$ declare out jsonb; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if p_group_by='status' then select coalesce(jsonb_agg(jsonb_build_object('status',q.v,p_alias,q.c)),'[]'::jsonb) into out from(select status v,count(*) c from public.toolbox_issues where workspace_id=p_workspace_id and archived_at is null group by status)q; elsif p_group_by in('date','targetDate') then select coalesce(jsonb_agg(jsonb_build_object(p_group_by,q.v,p_alias,q.c)),'[]'::jsonb) into out from(select target_date::text v,count(*) c from public.toolbox_issues where workspace_id=p_workspace_id and archived_at is null group by target_date)q; else out:='[]'::jsonb; end if; return out; end $$; create or replace function public.toolbox_issues_get_issue(p_workspace_id uuid,p_issue_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare r public.toolbox_issues%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select * into r from public.toolbox_issues where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null; if not found then raise exception 'Issue not found' using errcode='P0002'; end if; return private.toolbox_issue_json(r); end $$; create or replace function public.toolbox_issues_create_issue(p_workspace_id uuid,p_fields jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare r public.toolbox_issues%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; insert into public.toolbox_issues(workspace_id,name,status,person,target_date,time_tracking,payload,creator_user_id) values(p_workspace_id,left(trim(coalesce(p_fields->>'name','Untitled issue')),500),left(coalesce(nullif(p_fields->>'status',''),'Working on it'),80),coalesce(p_fields->'person','[]'::jsonb),case when nullif(left(coalesce(p_fields->>'date',''),10),'') is null then null else left(p_fields->>'date',10)::date end,coalesce(p_fields->'timeTracking','{"hours":0,"minutes":0}'::jsonb),p_fields-'name'-'status'-'person'-'date'-'timeTracking'-'_returnColumns',(select auth.uid())) returning * into r; insert into public.toolbox_issues_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type,detail) values(p_workspace_id,'issue',r.id::text,(select auth.uid()),'issue_created',jsonb_build_object('name',r.name)); return private.toolbox_issue_json(r); end $$; create or replace function public.toolbox_issues_update_issue(p_workspace_id uuid,p_issue_id text,p_updates jsonb,p_expected_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare r public.toolbox_issues%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select * into r from public.toolbox_issues where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null for update; if not found then raise exception 'Issue not found' using errcode='P0002'; end if; if p_expected_version is not null and r.version<>p_expected_version then raise exception 'stale issue version' using errcode='40001'; end if; update public.toolbox_issues set name=case when p_updates?'name' then left(trim(coalesce(p_updates->>'name','')),500) else name end,status=case when p_updates?'status' then left(coalesce(nullif(p_updates->>'status',''),status),80) else status end,person=case when p_updates?'person' then coalesce(p_updates->'person','[]'::jsonb) else person end,target_date=case when p_updates?'date' then case when nullif(left(coalesce(p_updates->>'date',''),10),'') is null then null else left(p_updates->>'date',10)::date end else target_date end,time_tracking=case when p_updates?'timeTracking' then coalesce(p_updates->'timeTracking',time_tracking) else time_tracking end,payload=payload||(p_updates-'name'-'status'-'person'-'date'-'timeTracking'-'personIds'-'targetDate'),version=version+1,updated_at=now() where workspace_id=p_workspace_id and id=r.id returning * into r; insert into public.toolbox_issues_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type,detail) values(p_workspace_id,'issue',r.id::text,(select auth.uid()),'issue_updated',p_updates); return private.toolbox_issue_json(r); end $$; create or replace function public.toolbox_issues_archive_issue(p_workspace_id uuid,p_issue_id text) returns jsonb language plpgsql security definer set search_path='' as $$ begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; update public.toolbox_issues set archived_at=now(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null; if not found then raise exception 'Issue not found' using errcode='P0002'; end if; insert into public.toolbox_issues_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type) values(p_workspace_id,'issue',p_issue_id,(select auth.uid()),'issue_archived'); return jsonb_build_object('success',true,'id',p_issue_id); end $$; revoke execute on function public.toolbox_issues_list_issues(uuid,jsonb,jsonb,integer,text),public.toolbox_issues_aggregate(uuid,text,text),public.toolbox_issues_get_issue(uuid,text),public.toolbox_issues_create_issue(uuid,jsonb),public.toolbox_issues_update_issue(uuid,text,jsonb,bigint),public.toolbox_issues_archive_issue(uuid,text) from public,anon; grant execute on function public.toolbox_issues_list_issues(uuid,jsonb,jsonb,integer,text),public.toolbox_issues_aggregate(uuid,text,text),public.toolbox_issues_get_issue(uuid,text),public.toolbox_issues_create_issue(uuid,jsonb),public.toolbox_issues_update_issue(uuid,text,jsonb,bigint),public.toolbox_issues_archive_issue(uuid,text) to authenticated;;
